def transform(grid):
    h, w = len(grid), len(grid[0])

    # Grid-line rows are the solid horizontal separators. The vertical
    # separators are identifiable as the columns that are not interior 9s.
    row_lines = [
        r for r in range(h)
        if all(v != 9 for v in grid[r])
    ]
    col_lines = [
        c for c in range(w)
        if all(grid[r][c] != 9 for r in range(h))
    ]

    # Include the left border as a separator when the input has one, and
    # omit the final boundary so the cells correspond to the repeated panels.
    if col_lines and col_lines[0] != 0:
        col_lines = [0] + col_lines

    rr = row_lines[1:-1]
    cc = col_lines[:-1]

    out = []
    for r in rr:
        row = []
        for c in cc:
            v = grid[r][c]
            row.append(v if v not in (3, 5, 9) else 9)
        out.append(row)
    return out
